function safePath(sessionId: string): string {
  if (!/^[a-zA-Z0-9_-]+$/.test(sessionId)) {
    throw new Error("Invalid session ID");
  }
  const resolved = resolve(SESSION_DIR, `${sessionId}.json`);
  if (!resolved.startsWith(resolve(SESSION_DIR) + "/")) {
    throw new Error("Path traversal detected");
  }
  return resolved;
}
```

